    shaders::ShaderFilterPreset shader_filter = shaders::ShaderFilterPreset::Nearest;
    bool weather_ambient_bloom = true;
    int audio_volume_percent = 100; // 0 .. 100 (step 10)
    bool audio_muted = false;
